#include <sys/time.h>
#include <riscv_vector.h>

#include "common.h"

real_t stream_dot(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dot_acc = 0.0;
    const size_t n = LEN_1D;
    const size_t vlmax = __riscv_vsetvlmax_e64m1();

    for (int nl = 0; nl < iterations; nl++) {
        real_t local = 0.0;
        size_t i = 0;

        while (i < n) {
            size_t vl = __riscv_vsetvl_e64m1(n - i);

            vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&a[i], vl);
            vfloat64m1_t vb = __riscv_vle64_v_f64m1((const double *)&b[i], vl);
            vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vb, vl);

            double tmp[64];
            __riscv_vse64_v_f64m1(tmp, vm, vl);
            for (size_t j = 0; j < vl; ++j) {
                local += (real_t)tmp[j];
            }

            i += vl;
        }

        dot_acc += local;
        dummy(a, b, NULL, NULL, NULL, local);
    }

    x[0] = dot_acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#include <stddef.h>
#include <stdint.h>
#include <sys/time.h>
#include <riscv_vector.h>

#include "common.h"

real_t stream_mul(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t alpha = 0.42;
    const size_t n = LEN_1D;

    for (int nl = 0; nl < iterations; nl++) {
        size_t i = 0;
        while (i < n) {
            size_t vl = __riscv_vsetvl_e64m1(n - i);
            vfloat64m1_t vc = __riscv_vle64_v_f64m1((const real_t *)&c[i], vl);
            vfloat64m1_t vb = __riscv_vfmul_vf_f64m1(vc, alpha, vl);
            __riscv_vse64_v_f64m1((real_t *)&b[i], vb, vl);
            i += vl;
        }
        dummy(b, c, NULL, NULL, NULL, alpha);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#include <stddef.h>
#include <stdint.h>
#include <sys/time.h>
#include <riscv_vector.h>

#include "common.h"

real_t stream_triad(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t alpha = 0.42;
    const size_t n = LEN_1D;

    for (int nl = 0; nl < iterations; nl++) {
        size_t i = 0;
        while (i < n) {
            size_t vl = __riscv_vsetvl_e64m1(n - i);

            vfloat64m1_t vb = __riscv_vle64_v_f64m1((const real_t *)&b[i], vl);
            vfloat64m1_t vc = __riscv_vle64_v_f64m1((const real_t *)&c[i], vl);
            vfloat64m1_t valpha = __riscv_vfmv_v_f_f64m1(alpha, vl);
            vfloat64m1_t vres = __riscv_vfadd_vv_f64m1(vb, __riscv_vfmul_vv_f64m1(valpha, vc, vl), vl);

            __riscv_vse64_v_f64m1((real_t *)&a[i], vres, vl);
            i += vl;
        }

        dummy(a, b, c, NULL, NULL, alpha);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}
